def fetch_active_tles(max_objects: int = None) -> list[dict]:
    """Fetch active satellite TLEs from CelesTrak (free, no auth)."""
    print("Fetching active satellite TLEs from CelesTrak ...")
    resp = requests.get(f"{CELESTRAK_URL}?GROUP=active&FORMAT=json", timeout=60)
    resp.raise_for_status()
    tles = resp.json()
    print(f"  Got {len(tles)} active satellites")

    if max_objects and len(tles) > max_objects:
        tles = tles[:max_objects]
        print(f"  Truncated to {max_objects} for quick mode")

    return tles


def fetch_starlink_tles() -> list[dict]:
    """Fetch Starlink TLEs separately (largest constellation)."""
    print("Fetching Starlink TLEs ...")
    resp = requests.get(f"{CELESTRAK_URL}?GROUP=starlink&FORMAT=json", timeout=60)
    resp.raise_for_status()
    tles = resp.json()
    print(f"  Got {len(tles)} Starlink satellites")
    return tles


def fetch_supplemental_tles(active_tles: list[dict]) -> list[dict]:
    """Fetch fresh TLEs for CDM objects not in the active satellite group.

    CelesTrak has TLEs for debris, old payloads, and rocket bodies — they're
    just not in GROUP=active. This fetches them individually by NORAD ID.

    Unlike active TLEs which come in a single bulk request, supplemental
    objects must be fetched one-by-one. All known supplemental IDs are
    re-fetched every run to keep orbital elements current (debris orbits
    decay, elements change daily). ~163 objects at 0.3s spacing = ~50s.

    The ID list is persisted so new CDM objects are automatically included
    in future runs even before the next CDM fetch.

    Returns list of supplemental TLE dicts (same format as active TLEs).
    """
    CDM_STORE = LOG_DIR / "cdm_store.jsonl"
    CACHE_PATH = SNAPSHOT_DIR / "supplemental.json"
    ID_LIST_PATH = SNAPSHOT_DIR / "supplemental_ids.json"

    # Build the cumulative set of NORAD IDs we need to track.
    # Sources: CDM store + previously saved ID list (prospective)
    cdm_norad_ids = set()

    # Load previously saved ID list (persists across runs)
    if ID_LIST_PATH.exists():
        try:
            with open(ID_LIST_PATH) as f:
                saved_ids = json.load(f)
            cdm_norad_ids.update(saved_ids)
        except (json.JSONDecodeError, ValueError):
            pass

    # Add any new IDs from CDM store
    if CDM_STORE.exists():
        with open(CDM_STORE) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    cdm = json.loads(line)
                    s1 = cdm.get("sat1_norad", 0)
                    s2 = cdm.get("sat2_norad", 0)
                    if s1 > 0:
                        cdm_norad_ids.add(s1)
                    if s2 > 0:
                        cdm_norad_ids.add(s2)
                except json.JSONDecodeError:
                    continue

    if not cdm_norad_ids:
        print("  No supplemental NORAD IDs known — skipping")
        return []

    # Save cumulative ID list for future runs
    SNAPSHOT_DIR.mkdir(parents=True, exist_ok=True)
    with open(ID_LIST_PATH, "w") as f:
        json.dump(sorted(cdm_norad_ids), f)

    # Filter to IDs not already in the active TLE set
    active_ids = {int(t.get("NORAD_CAT_ID", 0)) for t in active_tles}
    ids_to_fetch = sorted(cdm_norad_ids - active_ids)

    if not ids_to_fetch:
        print("  All CDM objects found in active TLEs — no supplemental fetch needed")
        return []

    print(f"  Supplemental TLE fetch: {len(ids_to_fetch)} objects "
          f"(of {len(cdm_norad_ids)} tracked, {len(cdm_norad_ids) - len(ids_to_fetch)} already in active)")

    # Fetch fresh TLEs from CelesTrak (every run, to keep elements current)
    # Cap at 120s total to prevent pipeline timeout
    fetched_tles: dict[int, dict] = {}
    n_failed = 0
    fetch_start = time.time()
    MAX_SUPPLEMENTAL_SECONDS = 120
    for i, norad_id in enumerate(ids_to_fetch):
        if time.time() - fetch_start > MAX_SUPPLEMENTAL_SECONDS:
            print(f"    Supplemental fetch time limit ({MAX_SUPPLEMENTAL_SECONDS}s) reached at {i}/{len(ids_to_fetch)}")
            break
        try:
            url = f"{CELESTRAK_URL}?CATNR={norad_id}&FORMAT=json"
            resp = requests.get(url, timeout=10)
            if resp.status_code == 200:
                data = resp.json()
                if isinstance(data, list) and len(data) > 0:
                    fetched_tles[norad_id] = data[0]
                    if (i + 1) % 50 == 0:
                        print(f"    Fetched {i + 1}/{len(ids_to_fetch)}")
                else:
                    n_failed += 1
            else:
                n_failed += 1
        except Exception as e:
            n_failed += 1
            if n_failed <= 3:
                print(f"    NORAD {norad_id}: {e}")

        # Rate limit: 0.1s between requests (CelesTrak allows rapid queries)
        if i < len(ids_to_fetch) - 1:
            time.sleep(0.1)

    print(f"  Fetched {len(fetched_tles)} fresh supplemental TLEs"
          + (f" ({n_failed} failed)" if n_failed else ""))

    # Save as supplemental.json (overwritten each run with fresh data)
    with open(CACHE_PATH, "w") as f:
        json.dump(list(fetched_tles.values()), f)

    return list(fetched_tles.values())


def screen_pairs(tles: list[dict], alt_band_km: float = 50.0, raan_band_deg: float = 30.0) -> list[dict]:
    """Fast pairwise orbital screening using altitude + RAAN proximity.

    Filters ~99% of pairs, keeping only those in similar orbital shells.
    """
    n = len(tles)
    print(f"\nScreening {n} satellites for close approaches ...")

    # Extract orbital elements
    altitudes = np.zeros(n)
    raans = np.zeros(n)
    norad_ids = []
    names = []

    for i, tle in enumerate(tles):
        mm = float(tle.get("MEAN_MOTION", 0))
        sma = mean_motion_to_sma(mm)
        altitudes[i] = sma - EARTH_RADIUS_KM
        raans[i] = float(tle.get("RA_OF_ASC_NODE", 0))
        norad_ids.append(int(tle.get("NORAD_CAT_ID", 0)))
        names.append(tle.get("OBJECT_NAME", "UNKNOWN"))

    # Vectorized filtering: altitude overlap
    alt_diff = np.abs(altitudes[:, None] - altitudes[None, :])
    alt_mask = alt_diff < alt_band_km

    # RAAN proximity (handle wrap-around at 360°)
    raan_diff = np.abs(raans[:, None] - raans[None, :])
    raan_diff = np.minimum(raan_diff, 360 - raan_diff)
    raan_mask = raan_diff < raan_band_deg

    # Combine: both conditions AND upper triangle only (avoid duplicates)
    combined = alt_mask & raan_mask & np.triu(np.ones((n, n), dtype=bool), k=1)
    pairs_i, pairs_j = np.where(combined)

    print(f"  Found {len(pairs_i)} candidate pairs (from {n*(n-1)//2} total)")

    # Also extract inclination for better scoring
    inclinations = np.zeros(n)
    eccentricities = np.zeros(n)
    for i, tle in enumerate(tles):
        inclinations[i] = float(tle.get("INCLINATION", 0))
        eccentricities[i] = float(tle.get("ECCENTRICITY", 0))

    # Compute inclination differences for candidate pairs
    inc_diff = np.abs(inclinations[:, None] - inclinations[None, :])

    # Score candidates: combine altitude gap, RAAN proximity, and inclination
    candidates = []
    for idx in range(len(pairs_i)):
        i, j = int(pairs_i[idx]), int(pairs_j[idx])
        alt_gap = abs(altitudes[i] - altitudes[j])
        avg_alt = (altitudes[i] + altitudes[j]) / 2
        rd = float(raan_diff[i, j])
        id_ = float(inc_diff[i, j])

        # Composite risk heuristic:
        #   - altitude closeness (0-1): closer = higher risk
        #   - RAAN proximity (0-1): same plane = higher risk
        #   - inclination similarity (0-1): coplanar = higher risk
        alt_score = max(0, 1.0 - alt_gap / alt_band_km)
        raan_score = max(0, 1.0 - rd / raan_band_deg)
        inc_score = max(0, 1.0 - id_ / 10.0)  # 10° inc diff -> 0 score

        # Weighted combination: RAAN matters most for close approaches
        risk_score = 0.2 * alt_score + 0.5 * raan_score + 0.3 * inc_score

        candidates.append({
            "sat1_norad": norad_ids[i],
            "sat2_norad": norad_ids[j],
            "sat1_name": names[i],
            "sat2_name": names[j],
            "altitude_km": round(avg_alt, 1),
            "alt_gap_km": round(alt_gap, 2),
            "raan_diff_deg": round(rd, 2),
            "inc_diff_deg": round(id_, 2),
            "risk_score": round(risk_score, 4),
        })

    # Sort by risk score descending
    candidates.sort(key=lambda c: c["risk_score"], reverse=True)
    return candidates


