def score_with_pairwise_model(
    candidates: list[dict],
    pairwise_model,
    tles: list[dict],
) -> list[dict]:
    """Score candidates with the CDM-supervised pairwise risk model.

    Adds pairwise_risk_score and pairwise_log10_pc to each candidate.
    """
    if pairwise_model is None or not candidates:
        return candidates

    # Build TLE lookup
    tle_by_norad: dict[int, dict] = {}
    for tle in tles:
        nid = int(tle.get("NORAD_CAT_ID", 0))
        if nid > 0:
            tle_by_norad[nid] = tle

    # Build (sat1_tle, sat2_tle) pairs for batch feature computation
    pairs = []
    valid_indices = []
    for i, cand in enumerate(candidates):
        tle1 = tle_by_norad.get(cand["sat1_norad"])
        tle2 = tle_by_norad.get(cand["sat2_norad"])
        if tle1 is not None and tle2 is not None:
            pairs.append((tle1, tle2))
            valid_indices.append(i)

    if not pairs:
        return candidates

    # Compute features and predict
    from src.data.pairwise_features import compute_batch_features
    X = compute_batch_features(pairs, all_tles=tles)
    risk_scores = pairwise_model.predict_risk(X)
    log10_pcs = pairwise_model.predict(X)

    for j, idx in enumerate(valid_indices):
        candidates[idx]["pairwise_risk_score"] = round(float(risk_scores[j]), 6)
        candidates[idx]["pairwise_log10_pc"] = round(float(log10_pcs[j]), 2)

    n_high = sum(1 for s in risk_scores if s > 0.5)
    print(f"  CSPR scored {len(pairs)} pairs: {n_high} high-risk (>0.5)")

    return candidates


def score_with_model(candidates: list[dict], model) -> list[dict]:
    """Re-score candidates using the trained baseline model."""
    if model is None or not candidates:
        return candidates

    altitudes = np.array([c["altitude_km"] for c in candidates])
    risk_probs, miss_estimates = model.predict(altitudes)

    for i, cand in enumerate(candidates):
        cand["model_risk_score"] = round(float(risk_probs[i]), 6)
        cand["model_miss_km"] = round(float(np.expm1(miss_estimates[i])), 1)
        cand["model_used"] = "OrbitalShellBaseline"

    # Re-sort by model risk score
    candidates.sort(key=lambda c: c.get("model_risk_score", 0), reverse=True)
    return candidates


def load_maneuver_history() -> dict[int, list[dict]]:
    """Load maneuver history keyed by NORAD ID."""
    history: dict[int, list[dict]] = {}
    if not MANEUVER_HISTORY_PATH.exists():
        return history
    with open(MANEUVER_HISTORY_PATH) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            record = json.loads(line)
            nid = record.get("norad_id", 0)
            if nid > 0:
                history.setdefault(nid, []).append(record)
    return history


def _json_default(obj):
    """Handle numpy types that json.dumps can't serialize."""
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        return float(obj)
    if isinstance(obj, (np.bool_,)):
        return bool(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def save_maneuver_history(enriched_maneuvers: list[dict]):
    """Append enriched maneuvers to history file."""
    MANEUVER_HISTORY_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(MANEUVER_HISTORY_PATH, "a") as f:
        for m in enriched_maneuvers:
            f.write(json.dumps(m, default=_json_default) + "\n")


def enrich_maneuvers(
    maneuvers: list[dict],
    prev_tles: list[dict],
    today_tles: list[dict],
) -> list[dict]:
    """Classify maneuvers, run counterfactuals, and cross-reference CDMs.

    Unlike earlier versions that only ran counterfactual for heuristic-flagged
    "likely avoidance" maneuvers, we now run counterfactual for ALL maneuvers
    (capped at 500) and use the result as the PRIMARY avoidance signal.

    This is critical because not every maneuver is avoidance — Starlink does
    thousands of orbit-raising and phasing burns daily. Only maneuvers with
    collision evidence (counterfactual close approach or CDM confirmation)
    should be labeled as avoidance for training.

    Returns enriched maneuver list with all Phase A/B/C fields.
    """
    MAX_COUNTERFACTUAL = 2000  # Cap for runtime budget (old pipeline ran ~1600 in <6 min)

    # Phase A: Initial classification (heuristic, refined by Phase B)
    print("  Enriching maneuvers ...")
    history = load_maneuver_history()

    enriched = []
    for m in maneuvers:
        nid = m["norad_id"]
        sat_history = history.get(nid, [])
        em = classify_maneuver(m, sat_history)
        enriched.append(em)

    n_heuristic_avoidance = sum(1 for e in enriched if e.get("likely_avoidance"))
    n_sk = sum(1 for e in enriched if e.get("is_stationkeeping"))
    print(f"    Heuristic classification: {n_heuristic_avoidance} likely avoidance, "
          f"{n_sk} stationkeeping, {len(enriched) - n_heuristic_avoidance - n_sk} other")

    # Phase B: SGP4 counterfactual for ALL maneuvers (not just heuristic-flagged)
    # Priority order:
    #   1. Heuristic likely-avoidance (confirm or clear them)
    #   2. Non-avoidance sorted by delta-v ascending (small burns may be missed avoidance)
    # The old pipeline ran CF for ~1600 likely-avoidance in <6 min, so we have budget.
    heuristic_avoidance = [e for e in enriched if e.get("likely_avoidance")]
    non_avoidance = sorted(
        [e for e in enriched if not e.get("likely_avoidance")],
        key=lambda e: abs(e.get("delta_v_m_s", 0)),  # small delta-v first (missed avoidance?)
    )
    counterfactual_candidates = (heuristic_avoidance + non_avoidance)[:MAX_COUNTERFACTUAL]

    try:
        from src.data.counterfactual import (
            propagate_counterfactual,
            find_nearby_satellites,
            SGP4_AVAILABLE,
        )
        if SGP4_AVAILABLE and counterfactual_candidates:
            # Build TLE lookup for pre-maneuver orbits
            prev_by_id = {}
            for tle in prev_tles:
                nid = int(tle.get("NORAD_CAT_ID", 0))
                if nid > 0:
                    prev_by_id[nid] = tle

            n_counterfactual = 0
            n_close = 0     # < 25 km
            n_collisions = 0  # < 1 km
            for em in counterfactual_candidates:
                nid = em["norad_id"]
                pre_tle = prev_by_id.get(nid)
                if not pre_tle:
                    continue

                nearby = find_nearby_satellites(pre_tle, today_tles)
                if not nearby:
                    continue

                result = propagate_counterfactual(pre_tle, nearby)
                min_dist = result.get("min_distance_km")
                em["counterfactual_min_distance_km"] = min_dist
                em["would_have_collided"] = result.get("would_have_collided", False)
                em["counterfactual_closest_norad"] = result.get("closest_norad_id", 0)
                n_counterfactual += 1

                if min_dist is not None and min_dist < 25.0:
                    n_close += 1
                if result.get("would_have_collided"):
                    n_collisions += 1

            print(f"    Counterfactual: {n_counterfactual}/{len(counterfactual_candidates)} propagated, "
                  f"{n_close} close (<25km), {n_collisions} would-have-collided (<1km)")
        elif not SGP4_AVAILABLE:
            print("    Counterfactual: sgp4 not installed, skipping")
    except Exception as e:
        print(f"    Counterfactual failed (non-critical): {e}")

    # Phase B2: Refine avoidance classification using counterfactual evidence
    # Override heuristic classification with physics-based evidence
    CLOSE_APPROACH_THRESHOLD_KM = 25.0
    for em in enriched:
        cf_dist = em.get("counterfactual_min_distance_km")
        if cf_dist is not None and cf_dist < CLOSE_APPROACH_THRESHOLD_KM:
            # Counterfactual shows a close approach — this IS avoidance
            em["likely_avoidance"] = True
            em["avoidance_evidence"] = "counterfactual"
            em["avoidance_confidence"] = _distance_to_confidence(
                cf_dist,
                delta_v_m_s=abs(em.get("delta_v_m_s", 0)),
                constellation=em.get("constellation", ""),
            )
        elif em.get("likely_avoidance"):
            # Heuristic flagged it but no counterfactual evidence
            # Downgrade confidence — might be orbit-raising, phasing, etc.
            if cf_dist is not None and cf_dist >= CLOSE_APPROACH_THRESHOLD_KM:
                # We checked and it's NOT a close approach — unflag
                em["likely_avoidance"] = False
                em["avoidance_evidence"] = "counterfactual_cleared"
                em["avoidance_confidence"] = 0.0
            else:
                # Counterfactual didn't run (no prev TLE, no neighbors) — keep heuristic but low confidence
                em["avoidance_evidence"] = "heuristic_only"
                em["avoidance_confidence"] = 0.3

    n_confirmed = sum(1 for e in enriched if e.get("avoidance_evidence") == "counterfactual")
    n_cleared = sum(1 for e in enriched if e.get("avoidance_evidence") == "counterfactual_cleared")
    n_heuristic_only = sum(1 for e in enriched if e.get("avoidance_evidence") == "heuristic_only")
    n_avoidance_final = sum(1 for e in enriched if e.get("likely_avoidance"))
    print(f"    Refined avoidance: {n_avoidance_final} total "
          f"({n_confirmed} counterfactual-confirmed, {n_cleared} cleared, "
          f"{n_heuristic_only} heuristic-only)")

    # Starlink pattern tracking — log avoidance threshold distribution
    starlink_avoidance = [
        e for e in enriched
        if e.get("constellation") == "starlink"
        and e.get("avoidance_evidence") == "counterfactual"
        and e.get("counterfactual_min_distance_km") is not None
    ]
    if starlink_avoidance:
        sl_dists = [e["counterfactual_min_distance_km"] for e in starlink_avoidance]
        sl_dvs = [e.get("delta_v_m_s", 0) for e in starlink_avoidance]
        print(f"    Starlink avoidance insights: {len(starlink_avoidance)} confirmed, "
              f"counterfactual dist range [{min(sl_dists):.1f}, {max(sl_dists):.1f}] km, "
              f"delta-v range [{min(sl_dvs):.3f}, {max(sl_dvs):.3f}] m/s")

    # Phase C: Space-Track CDM cross-reference — PRIMARY label source
    # CDM Pc values are ground truth (SP ephemerides + covariance).
    # When available, CDM evidence overrides both heuristic AND counterfactual.
    all_norad_ids = [e["norad_id"] for e in enriched]
    try:
        cdm_results = check_cdm_for_norad_ids(all_norad_ids, cache_dir=LOG_DIR)
        n_with_cdm = 0
        for em in enriched:
            nid = em["norad_id"]
            cdms = cdm_results.get(nid, [])
            if cdms:
                max_pc = max(c["pc"] for c in cdms)
                min_miss = min(c["miss_distance_km"] for c in cdms)
                em["has_cdm"] = True
                em["cdm_pc"] = max_pc
                em["cdm_miss_distance_km"] = min_miss
                em["cdm_count"] = len(cdms)
                # CDM-derived label (ground truth)
                label, weight = cdm_pc_to_label(max_pc)
                em["cdm_risk_label"] = label
                em["cdm_sample_weight"] = weight
                # CDM with Pc > 1e-6 confirms avoidance (Starlink threshold)
                if max_pc >= 1e-6:
                    em["likely_avoidance"] = True
                    em["avoidance_evidence"] = "cdm_confirmed"
                    em["avoidance_confidence"] = min(1.0, label)
                n_with_cdm += 1
            else:
                em["has_cdm"] = False
        if n_with_cdm:
            print(f"    CDM cross-ref: {n_with_cdm}/{len(enriched)} maneuvers have CDM data")
        else:
            print("    CDM cross-ref: no CDMs found (credentials may not be set)")
    except Exception as e:
        print(f"    CDM cross-ref skipped: {e}")

    # Save enriched maneuvers to history
    save_maneuver_history(enriched)

    return enriched


def _distance_to_confidence(dist_km: float, delta_v_m_s: float = 0.0,
                            constellation: str = "") -> float:
    """Convert counterfactual minimum distance to avoidance confidence score.

    Thresholds calibrated against:
      - TLE/SGP4 accuracy: 0.8 ± 0.3 km instantaneous, ~1.5 km/day growth
        (Levit & Marshall 2010). After 1-day propagation, combined 1-sigma
        for two satellites ≈ 3.3 km, 3-sigma ≈ 10 km.
      - 18 SDS screening volume: 0.5 km radial × 17 km in-track × 20 km
        cross-track (NASA NTRS 20170007928).
      - NASA CARA maneuver threshold: Pc > 1e-4 → typically miss dist 1-5 km.
      - Starlink autonomous avoidance: Pc > 1e-6, ~300K maneuvers/yr in 2025.
        Median delta-v for < 5 km approaches: 0.116 m/s (micro-burns).

    Maneuver type as additional signal:
      - Micro delta-v (< 0.5 m/s) + close approach → classic CAM pattern
      - Large delta-v (> 10 m/s) regardless of distance → orbit transfer, NOT avoidance
    """
    # Large maneuvers are almost never avoidance — orbit transfers, deorbits, reboosts
    if delta_v_m_s > 10.0:
        return 0.1  # Tiny residual confidence even at close range

    base_confidence = 0.0
    if dist_km < 1.0:
        base_confidence = 1.0    # Within radial screening threshold — orbits overlap
    elif dist_km < 5.0:
        base_confidence = 0.85   # Within 1-sigma TLE uncertainty — genuine conjunction
    elif dist_km < 10.0:
        base_confidence = 0.5    # Within 3-sigma — plausible but uncertain
    elif dist_km < 25.0:
        base_confidence = 0.2    # Outside 3-sigma — mostly TLE propagation noise

    # Boost confidence for micro-burns (classic Starlink CAM signature)
    if delta_v_m_s < 0.5 and base_confidence > 0:
        base_confidence = min(1.0, base_confidence + 0.1)

    return base_confidence


def validate_yesterday(
    logger: PredictionLogger,
    today_tles: list[dict],
    yesterday_str: str,
) -> dict:
    """Validate predictions using CDM Pc escalation as ground truth.

    Primary validation: For resolved CDM pairs (TCA in past), did the
    CDM forecast model correctly predict whether Pc exceeded 5e-4?

    Secondary: Maneuver detection continues for training data enrichment
    but is NOT used for accuracy reporting (maneuver != avoidance).
    """
    print(f"\nValidating predictions from {yesterday_str} ...")

    # Fetch CDMs from Space-Track (ONE query, uses 1 of 3 daily quota)
    # This populates the local CDM store BEFORE enrichment reads it.
    # Respects 8-hour rate limit internally — safe to call every run.
    try:
        fetch_and_store_cdms(lookback_days=3, min_pc=1e-7, store_path=LOG_DIR / "cdm_store.jsonl")
    except Exception as e:
        print(f"  Space-Track CDM fetch skipped: {e}")

    # Load yesterday's TLE snapshot
    yesterday_snapshot = SNAPSHOT_DIR / f"{yesterday_str}.json"
    if not yesterday_snapshot.exists():
        print(f"  No TLE snapshot for {yesterday_str} — skipping validation")
        return {"validated": False, "reason": "no_snapshot"}

    prev_tles = load_tle_snapshot(yesterday_snapshot)

    # Detect maneuvers with constellation-aware thresholds
    maneuvers = detect_maneuvers_dual_threshold(prev_tles, today_tles)
    print(f"  Detected {len(maneuvers)} maneuvers since yesterday")

    # Enrich maneuvers (classify, counterfactual, CDM)
    enriched_maneuvers = enrich_maneuvers(maneuvers, prev_tles, today_tles)

    # Build maneuver lookup
    maneuvered_ids = {m["norad_id"] for m in enriched_maneuvers}
    maneuver_by_id = {m["norad_id"]: m for m in enriched_maneuvers}

    # Load yesterday's predictions
    predictions = logger.get_predictions_for_date(yesterday_str)
    if not predictions:
        print(f"  No predictions found for {yesterday_str}")
        return {
            "validated": True,
            "n_maneuvers": len(enriched_maneuvers),
            "n_predictions": 0,
            "top_maneuvers": enriched_maneuvers[:10],
        }

    # Check predictions against maneuvers
    outcomes = []
    correct = 0
    total_checked = 0

    for pred in predictions:
        sat1 = pred.get("sat1_norad", 0)
        sat2 = pred.get("sat2_norad", 0)
        risk = pred.get("model_risk_score", pred.get("risk_score", 0))

        sat1_maneuvered = sat1 in maneuvered_ids
        sat2_maneuvered = sat2 in maneuvered_ids
        either_maneuvered = sat1_maneuvered or sat2_maneuvered

        outcome = {
            "sat1_norad": sat1,
            "sat2_norad": sat2,
            "sat1_name": pred.get("sat1_name", ""),
            "sat2_name": pred.get("sat2_name", ""),
            "predicted_risk": risk,
            "sat1_maneuvered": sat1_maneuvered,
            "sat2_maneuvered": sat2_maneuvered,
            "either_maneuvered": either_maneuvered,
        }

        if sat1_maneuvered and sat1 in maneuver_by_id:
            m = maneuver_by_id[sat1]
            outcome["sat1_delta_a_m"] = m["delta_a_m"]
            outcome["sat1_delta_v_m_s"] = m["delta_v_m_s"]

        if sat2_maneuvered and sat2 in maneuver_by_id:
            m = maneuver_by_id[sat2]
            outcome["sat2_delta_a_m"] = m["delta_a_m"]
            outcome["sat2_delta_v_m_s"] = m["delta_v_m_s"]

        # Add enrichment fields from whichever sat maneuvered
        maneuvered_sat = None
        if sat1_maneuvered and sat1 in maneuver_by_id:
            maneuvered_sat = maneuver_by_id[sat1]
        elif sat2_maneuvered and sat2 in maneuver_by_id:
            maneuvered_sat = maneuver_by_id[sat2]

        # Always stamp enrichment_version so we can distinguish
        # new-pipeline outcomes from legacy ones in weekly_finetune
        outcome["enrichment_version"] = 1

        if maneuvered_sat:
            outcome["magnitude_class"] = maneuvered_sat.get("magnitude_class")
            outcome["constellation"] = maneuvered_sat.get("constellation")
            outcome["is_stationkeeping"] = maneuvered_sat.get("is_stationkeeping")
            outcome["likely_avoidance"] = maneuvered_sat.get("likely_avoidance")
            outcome["avoidance_evidence"] = maneuvered_sat.get("avoidance_evidence")
            outcome["avoidance_confidence"] = maneuvered_sat.get("avoidance_confidence", 0.0)
            outcome["has_cdm"] = maneuvered_sat.get("has_cdm", False)
            outcome["cdm_pc"] = maneuvered_sat.get("cdm_pc")
            outcome["cdm_miss_distance_km"] = maneuvered_sat.get("cdm_miss_distance_km")
            outcome["counterfactual_min_distance_km"] = maneuvered_sat.get("counterfactual_min_distance_km")
            outcome["would_have_collided"] = maneuvered_sat.get("would_have_collided", False)

        outcomes.append(outcome)

        # Legacy maneuver-based tracking (for training data, NOT accuracy)
        if risk > 0.1:
            total_checked += 1
            if either_maneuvered:
                correct += 1

    # Log outcomes from predicted pairs
    if outcomes:
        logger.log_outcomes(yesterday_str, outcomes)

    # --- Maneuver-derived outcomes ---
    # Log detected maneuvers as training examples, but ONLY those with
    # collision evidence. Not every maneuver is avoidance — Starlink alone
    # does thousands of orbit-raising/phasing burns daily. We need to see
    # evidence that the pre-maneuver orbit would have led to a close approach.
    #
    # Evidence sources (in order of reliability):
    #   1. CDM confirmed (Space-Track has a conjunction record)
    #   2. Counterfactual < 25 km (SGP4 propagation shows close approach)
    #   3. Heuristic-only (no physics evidence — logged at low confidence)
    #
    # This lets us infer avoidance architecture — e.g. Starlink's autonomous
    # system consistently maneuvers when counterfactual distance < X km.
    MAX_MANEUVER_OUTCOMES = 200
    predicted_norad_ids = set()
    for pred in predictions:
        predicted_norad_ids.add(pred.get("sat1_norad", 0))
        predicted_norad_ids.add(pred.get("sat2_norad", 0))

    maneuver_outcomes = []
    # Sort by avoidance confidence (counterfactual-confirmed first, then by distance)
    sorted_maneuvers = sorted(
        enriched_maneuvers,
        key=lambda m: (
            m.get("avoidance_confidence", 0),
            -1.0 * (m.get("counterfactual_min_distance_km") or 9999),
        ),
        reverse=True,
    )
    n_evidence_based = 0
    n_negative = 0
    for m in sorted_maneuvers:
        if len(maneuver_outcomes) >= MAX_MANEUVER_OUTCOMES:
            break
        nid = m["norad_id"]
        # Skip if already covered by a prediction-based outcome
        if nid in predicted_norad_ids:
            continue

        cf_dist = m.get("counterfactual_min_distance_km")
        has_cdm = m.get("has_cdm", False)
        evidence = m.get("avoidance_evidence", "")
        confidence = m.get("avoidance_confidence", 0.0)

        # Determine if this has collision evidence
        has_collision_evidence = (
            has_cdm
            or (cf_dist is not None and cf_dist < 25.0)
        )

        # Also log maneuvers with NO collision evidence as negative examples
        # (satellite maneuvered but NOT for avoidance — orbit maintenance)
        # This teaches the model what non-avoidance maneuvers look like
        is_negative = (
            cf_dist is not None
            and cf_dist >= 25.0
            and not has_cdm
        )

        if not has_collision_evidence and not is_negative:
            continue  # No counterfactual data at all — skip

        # The maneuvering satellite is sat1; counterfactual closest is sat2
        closest_norad = m.get("counterfactual_closest_norad") or 0
        outcome = {
            "sat1_norad": nid,
            "sat2_norad": closest_norad,
            "sat1_name": m.get("name", ""),
            "sat2_name": "",
            "predicted_risk": 0.0,  # our model didn't predict this pair
            "sat1_maneuvered": True,
            "sat2_maneuvered": False,
            "either_maneuvered": has_collision_evidence,  # Only True with evidence
            "source": "maneuver_detection",
            "enrichment_version": 3,  # v3 = CDM-primary + counterfactual fallback
            "avoidance_evidence": evidence,
            "avoidance_confidence": confidence,
            "magnitude_class": m.get("magnitude_class"),
            "constellation": m.get("constellation"),
            "is_stationkeeping": m.get("is_stationkeeping"),
            "likely_avoidance": m.get("likely_avoidance", False),
            "has_cdm": has_cdm,
            "cdm_pc": m.get("cdm_pc"),
            "cdm_miss_distance_km": m.get("cdm_miss_distance_km"),
            "cdm_risk_label": m.get("cdm_risk_label"),
            "cdm_sample_weight": m.get("cdm_sample_weight"),
            "counterfactual_min_distance_km": cf_dist,
            "would_have_collided": m.get("would_have_collided", False),
            "sat1_delta_a_m": m.get("delta_a_m", 0.0),
            "sat1_delta_v_m_s": m.get("delta_v_m_s", 0.0),
            "prediction_date": yesterday_str,
        }
        # Resolve sat2 name from TLE data
        if closest_norad:
            for tle in today_tles:
                if int(tle.get("NORAD_CAT_ID", 0)) == closest_norad:
                    outcome["sat2_name"] = tle.get("OBJECT_NAME", "")
                    break
        maneuver_outcomes.append(outcome)
        if has_collision_evidence:
            n_evidence_based += 1
        else:
            n_negative += 1

    if maneuver_outcomes:
        logger.log_outcomes(yesterday_str, maneuver_outcomes)
        print(f"  Maneuver-derived outcomes: {len(maneuver_outcomes)} logged "
              f"({n_evidence_based} with collision evidence, {n_negative} negative examples)")

    n_avoidance = sum(1 for m in enriched_maneuvers if m.get("likely_avoidance"))

    # --- Primary accuracy: CDM Pc escalation forecast ---
    # Train the CDM forecast model on accumulated data and report real metrics.
    cdm_accuracy = {}
    try:
        from src.model.cdm_forecast import CDMForecastModel
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        if cdm_store.exists():
            forecast_model = CDMForecastModel()
            cdm_metrics = forecast_model.train(str(cdm_store))
            test_metrics = cdm_metrics.get("test", {})
            if test_metrics:
                cdm_accuracy = {
                    "task": "Predict Pc > 5e-4 (maneuver planning threshold exceedance)",
                    "accuracy": test_metrics.get("accuracy", 0),
                    "precision": test_metrics.get("precision", 0),
                    "recall": test_metrics.get("recall", 0),
                    "f1": test_metrics.get("f1", 0),
                    "auc_pr": test_metrics.get("auc_pr", 0),
                    "n_test": test_metrics.get("n", 0),
                    "n_train": cdm_metrics.get("n_train", 0),
                    "n_positive": cdm_metrics.get("n_positive", 0),
                    "positive_rate": cdm_metrics.get("positive_rate", 0),
                    "mode": cdm_metrics.get("mode", "unknown"),
                }
                print(f"  CDM Forecast Validation (temporal test split):")
                print(f"    Task: Predict Pc > 5e-4 (maneuver planning threshold) before TCA")
                print(f"    Test accuracy: {test_metrics.get('accuracy', 0):.1%} "
                      f"(n={test_metrics.get('n', 0)})")
                print(f"    Precision: {test_metrics.get('precision', 0):.3f}, "
                      f"Recall: {test_metrics.get('recall', 0):.3f}, "
                      f"F1: {test_metrics.get('f1', 0):.3f}")
                print(f"    AUC-PR: {test_metrics.get('auc_pr', 0):.3f}")
            else:
                print(f"  CDM Forecast: {cdm_metrics.get('mode', 'heuristic')} mode "
                      f"({cdm_metrics.get('n_labeled', 0)} labeled pairs)")
    except Exception as e:
        print(f"  CDM forecast validation skipped: {e}")

    summary = {
        "validated": True,
        "prediction_date": yesterday_str,
        "n_maneuvers_total": len(enriched_maneuvers),
        "n_likely_avoidance": n_avoidance,
        "n_maneuver_outcomes_logged": len(maneuver_outcomes),
        "n_predictions": len(predictions),
        "cdm_forecast_accuracy": cdm_accuracy,
        "top_maneuvers": enriched_maneuvers[:10],
    }

    # --- CDM-sourced training data ---
    try:
        recent_cdms = fetch_recent_cdms(lookback_days=3, min_pc=1e-5)
        if recent_cdms:
            cdm_outcomes = []
            for cdm in recent_cdms[:200]:
                label, weight = cdm_pc_to_label(cdm["pc"])
                cdm_outcome = {
                    "sat1_norad": cdm["sat1_norad"],
                    "sat2_norad": cdm["sat2_norad"],
                    "sat1_name": cdm["sat1_name"],
                    "sat2_name": cdm["sat2_name"],
                    "predicted_risk": 0.0,
                    "sat1_maneuvered": False,
                    "sat2_maneuvered": False,
                    "either_maneuvered": label > 0.5,
                    "source": "cdm_direct",
                    "enrichment_version": 3,
                    "has_cdm": True,
                    "cdm_pc": cdm["pc"],
                    "cdm_miss_distance_km": cdm["miss_distance_km"],
                    "cdm_risk_label": label,
                    "cdm_sample_weight": weight,
                    "avoidance_evidence": "cdm_direct",
                    "avoidance_confidence": label,
                    "prediction_date": yesterday_str,
                }
                cdm_outcomes.append(cdm_outcome)
            if cdm_outcomes:
                logger.log_outcomes(yesterday_str, cdm_outcomes)
                n_high = sum(1 for c in cdm_outcomes if c["cdm_risk_label"] > 0.5)
                print(f"  CDM-sourced outcomes: {len(cdm_outcomes)} logged "
                      f"({n_high} high-Pc, {len(cdm_outcomes) - n_high} low-Pc)")
                summary["n_cdm_outcomes"] = len(cdm_outcomes)
    except Exception as e:
        print(f"  CDM-sourced outcomes skipped: {e}")

    print(f"  Maneuvers detected: {len(enriched_maneuvers)} "
          f"({n_avoidance} likely avoidance)")

    return summary


def export_webapp_tles(active_tles: list[dict]):
    """Export TLE snapshot to webapp-react/public/latest_tles.json.

    This provides a static fallback for the webapp when CelesTrak blocks
    the client IP. Fetches each webapp group separately so the webapp can
    color-code satellites (stations, starlink, debris, etc.). Active TLEs
    from the pipeline are tagged with _group='active'.

    TLEs are orbital elements, not positions — the webapp runs SGP4
    client-side for real-time propagation regardless of TLE source.
    """
    all_tles = []
    seen_ids = set()

    # Fetch group-specific TLEs for the webapp (small groups first)
    for group_id, celestrak_group in WEBAPP_GROUPS:
        try:
            resp = requests.get(
                f"{CELESTRAK_URL}?GROUP={celestrak_group}&FORMAT=json",
                timeout=30,
            )
            if resp.ok:
                group_tles = resp.json()
                for tle in group_tles:
                    nid = int(tle.get("NORAD_CAT_ID", 0))
                    if nid > 0 and nid not in seen_ids:
                        tle["_group"] = group_id
                        all_tles.append(tle)
                        seen_ids.add(nid)
                print(f"  Webapp TLE export: {group_id} = {len(group_tles)}")
        except Exception as e:
            print(f"  Webapp TLE export: {group_id} fetch failed: {e}")

    # Add active TLEs (those not already covered by specific groups)
    n_active_added = 0
    for tle in active_tles:
        nid = int(tle.get("NORAD_CAT_ID", 0))
        if nid > 0 and nid not in seen_ids:
            tle_copy = dict(tle)
            tle_copy["_group"] = "active"
            all_tles.append(tle_copy)
            seen_ids.add(nid)
            n_active_added += 1

    print(f"  Webapp TLE export: active (remaining) = {n_active_added}")
    print(f"  Webapp TLE export: {len(all_tles)} total TLEs")

    WEBAPP_TLE_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(WEBAPP_TLE_PATH, "w") as f:
        json.dump(all_tles, f)
    print(f"  Saved webapp TLE fallback to {WEBAPP_TLE_PATH}")


def main():
    parser = argparse.ArgumentParser(description="Daily conjunction prediction pipeline")
    parser.add_argument("--quick", action="store_true", help="Quick test with fewer satellites")
    parser.add_argument("--validate-only", action="store_true", help="Only validate yesterday")
    parser.add_argument("--top-k", type=int, default=500, help="Number of top pairs to log")
    parser.add_argument("--no-firebase", action="store_true", help="Skip Firebase, local only")
    args = parser.parse_args()

    today = datetime.now(tz=None)  # UTC-naive for compatibility
    today_str = today.strftime("%Y-%m-%d")
    yesterday_str = (today - timedelta(days=1)).strftime("%Y-%m-%d")

    print(f"{'='*60}")
    print(f"  Panacea Daily Prediction Pipeline")
    print(f"  Date: {today_str}")
    print(f"{'='*60}\n")

    # Initialize logger
    if args.no_firebase:
        # Force local-only by not setting env var
        import os
        os.environ.pop("FIREBASE_SERVICE_ACCOUNT", None)

    logger = PredictionLogger(local_dir=LOG_DIR)

    # Fetch today's TLEs
    max_objects = 1000 if args.quick else None
    active_tles = fetch_active_tles(max_objects=max_objects)

    # Fetch supplemental TLEs for CDM objects (debris, old payloads, etc.)
    if not args.quick:
        supplemental = fetch_supplemental_tles(active_tles)
        if supplemental:
            # Merge: add supplemental TLEs that aren't already in active set
            active_ids = {int(t.get("NORAD_CAT_ID", 0)) for t in active_tles}
            n_before = len(active_tles)
            for tle in supplemental:
                nid = int(tle.get("NORAD_CAT_ID", 0))
                if nid > 0 and nid not in active_ids:
                    active_tles.append(tle)
                    active_ids.add(nid)
            print(f"  Merged: {n_before} active + {len(active_tles) - n_before} "
                  f"supplemental = {len(active_tles)} total")

    # Save today's TLE snapshot for tomorrow's comparison
    SNAPSHOT_DIR.mkdir(parents=True, exist_ok=True)
    snapshot_path = SNAPSHOT_DIR / f"{today_str}.json"
    save_tle_snapshot(active_tles, snapshot_path)
    print(f"  Saved TLE snapshot to {snapshot_path}")

    # Export webapp TLE fallback (for when CelesTrak blocks the client)
    print("\nExporting webapp TLE fallback ...")
    try:
        export_webapp_tles(active_tles)
    except Exception as e:
        print(f"  Webapp TLE export failed (non-fatal): {e}")

    # Validate yesterday's predictions
    validation = validate_yesterday(logger, active_tles, yesterday_str)

    if args.validate_only:
        print("\n  Validation-only mode — done.")
        return

    # Screen pairs
    candidates = screen_pairs(active_tles)

    if not candidates:
        print("\n  No candidate pairs found. Done.")
        return

    # Score with baseline model
    model = load_baseline_model()
    candidates = score_with_model(candidates, model)

    # Score with CSPR pairwise model (CDM-supervised XGBoost)
    pairwise_model = load_pairwise_model()
    candidates = score_with_pairwise_model(candidates, pairwise_model, active_tles)

    # Re-rank: use CSPR pairwise score when available (CDM-supervised, much better
    # than altitude-only baseline). Fall back to baseline for pairs CSPR couldn't score.
    n_cspr = sum(1 for c in candidates if "pairwise_risk_score" in c)
    if n_cspr > 0:
        candidates.sort(
            key=lambda c: c.get("pairwise_risk_score", c.get("model_risk_score", 0)),
            reverse=True,
        )
        # Promote pairwise score to model_risk_score for downstream consumers
        for cand in candidates:
            if "pairwise_risk_score" in cand:
                cand["model_risk_score"] = cand["pairwise_risk_score"]
                cand["model_used"] = "CSPR-XGBoost"
        print(f"  Re-ranked by CSPR pairwise model ({n_cspr}/{len(candidates)} scored)")

    # Take top-K predictions
    top_k = min(args.top_k, len(candidates))
    top_predictions = candidates[:top_k]

    print(f"\n  Top {top_k} highest-risk pairs:")
    for i, pred in enumerate(top_predictions[:10]):
        risk = pred.get("model_risk_score", pred.get("risk_score", 0))
        model = pred.get("model_used", "?")
        pc_str = ""
        if "pairwise_log10_pc" in pred:
            pc_str = f" | log10Pc={pred['pairwise_log10_pc']:.1f}"
        print(f"    {i+1:3d}. {pred['sat1_name']:20s} <-> {pred['sat2_name']:20s} | "
              f"risk={risk:.4f} | alt={pred['altitude_km']:.0f}km | {model}{pc_str}")

    # Generate webapp alerts with forward TCA
    print("\nGenerating webapp alerts ...")
    generate_webapp_alerts(candidates, active_tles, today_str, top_k=20)

    # Log predictions
    print(f"\nLogging {top_k} predictions ...")
    logger.log_predictions(today_str, top_predictions)

    # Daily summary
    if not top_predictions:
        print("  WARNING: No predictions generated")
        top_risk = 0
    else:
        top_risk = top_predictions[0].get("model_risk_score",
                                           top_predictions[0].get("risk_score", 0))
    summary = {
        "date": today_str,
        "n_satellites_screened": len(active_tles),
        "n_candidate_pairs": len(candidates),
        "n_predictions_logged": top_k,
        "top_risk_score": top_risk,
        "validation": validation,
    }
    logger.log_daily_summary(today_str, summary)

    # Archive to HuggingFace (weekly)
    if today.weekday() == 6:  # Sunday
        print("\n  Weekly archival to HuggingFace ...")
        try:
            archive_to_huggingface(logger)
        except Exception as e:
            print(f"  HuggingFace archival failed: {e}")

    # Export pipeline stats for webapp dashboard
    print("\nExporting pipeline stats ...")
    try:
        export_pipeline_stats()
    except Exception as e:
        print(f"  Pipeline stats export failed (non-fatal): {e}")

    # Prefetch space weather indices (used by CDM forecast model)
    print("\nFetching space weather indices ...")
    try:
        from src.data.space_weather import SpaceWeatherCache
        sw_cache = SpaceWeatherCache()
        today_sw = sw_cache.get_indices(datetime.utcnow().strftime("%Y-%m-%d"))
        print(f"  F10.7={today_sw.get('f107', '?')}, Kp={today_sw.get('kp', '?')}, "
              f"Ap={today_sw.get('ap', '?')} (source: {today_sw.get('source', '?')})")
    except Exception as e:
        print(f"  Space weather fetch failed (non-fatal): {e}")

    # Run CDM forecast model — train, evaluate, predict, export
    print("\nRunning CDM Pc escalation forecast ...")
    try:
        from src.model.cdm_forecast import CDMForecastModel
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        if cdm_store.exists():
            forecast_model = CDMForecastModel()
            fmetrics = forecast_model.train(str(cdm_store))
            predictions = forecast_model.predict_all_pairs(str(cdm_store))
            # Save model checkpoint
            forecast_model.save(ROOT / "models" / "cdm_forecast.json")
            # Export webapp JSON with model metrics
            test_metrics = fmetrics.get("test", {})
            forecast_data = {
                "generated_at": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
                "model": "CDMForecastModel",
                "prediction_task": "Predict whether Pc will exceed 5e-4 (maneuver planning threshold) before TCA",
                "n_pairs": len(predictions),
                "n_pairs_exported": 0,  # updated after export_pairs is built
                "n_actionable": sum(1 for p in predictions if p["action_recommended"]),
                "n_escalating": sum(1 for p in predictions if p["risk_direction"] == "escalating"),
                "model_metrics": {
                    "mode": fmetrics.get("mode", "heuristic"),
                    "n_training_pairs": fmetrics.get("n_train", 0),
                    "n_test_pairs": fmetrics.get("n_test", 0),
                    "n_total_pairs": fmetrics.get("n_pairs_total", 0),
                    "positive_rate": fmetrics.get("positive_rate", 0),
                    "test_accuracy": test_metrics.get("accuracy", 0),
                    "test_precision": test_metrics.get("precision", 0),
                    "test_recall": test_metrics.get("recall", 0),
                    "test_f1": test_metrics.get("f1", 0),
                    "test_auc_pr": test_metrics.get("auc_pr", 0),
                },
                "pairs": [],
            }
            # Sticky tracking: merge today's predictions with any unresolved pairs
            # from yesterday's forecast that dropped out of today's top-K.
            # This ensures every pair is tracked continuously until TCA.
            now_str = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
            forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
            prev_unresolved = []
            if forecast_path.exists():
                try:
                    with open(forecast_path) as f:
                        prev_data = json.load(f)
                    today_keys = set()
                    for p in predictions:
                        k = (p.get("sat1_norad", 0), p.get("sat2_norad", 0), p.get("tca", "")[:10])
                        today_keys.add(k)
                    for p in prev_data.get("pairs", []):
                        tca_str = p.get("tca", "")
                        if tca_str and tca_str > now_str:
                            k = (p.get("sat1_norad", 0), p.get("sat2_norad", 0), tca_str[:10])
                            if k not in today_keys:
                                p["_carried_forward"] = True
                                prev_unresolved.append(p)
                except Exception:
                    pass  # if previous JSON is corrupted, skip

            future = [p for p in predictions if p.get("tca", "") > now_str]
            past = [p for p in predictions if p.get("tca", "") <= now_str]
            # Only export past pairs from last 30 days for webapp interaction.
            # All-time stats (track_record totals) still computed from full history.
            cutoff_30d = (datetime.utcnow() - timedelta(days=30)).strftime("%Y-%m-%dT")
            recent_past = [p for p in past if p.get("tca", "") >= cutoff_30d]
            # Combine: future + carried-forward unresolved + recent past, cap at 200
            MAX_EXPORT = 200
            all_export = future + prev_unresolved + recent_past
            export_pairs = all_export[:MAX_EXPORT]
            if prev_unresolved:
                print(f"  Carried forward {len(prev_unresolved)} unresolved pairs from yesterday")
            n_old_dropped = len(past) - len(recent_past)
            if n_old_dropped > 0:
                print(f"  Excluded {n_old_dropped} resolved pairs older than 30 days from webapp (data preserved on server)")
            if len(all_export) > MAX_EXPORT:
                print(f"  Capped export to {MAX_EXPORT}/{len(all_export)} pairs (webapp perf)")
            forecast_data["n_pairs_exported"] = len(export_pairs)
            for p in export_pairs:
                forecast_data["pairs"].append({
                    "sat1_name": p["sat1_name"],
                    "sat2_name": p["sat2_name"],
                    "sat1_norad": p["sat1_norad"],
                    "sat2_norad": p["sat2_norad"],
                    "tca": p["tca"],
                    "current_pc": p["current_pc"],
                    "forecast_pc": min(p["forecast_pc"], 1.0),
                    "exceedance_probability": p.get("exceedance_probability", 0),
                    "current_miss_km": p["current_miss_km"],
                    "forecast_miss_km": min(max(p["forecast_miss_km"], 0), 42000),
                    "risk_direction": p["risk_direction"],
                    "pc_trend": p["pc_trend"],
                    "confidence": p["confidence"],
                    "action_recommended": p["action_recommended"],
                    "n_updates": p["n_updates"],
                    "time_series": p["time_series"],
                })
            # Build prediction vs outcome track record for resolved pairs
            track_record = {
                "n_correct": 0, "n_wrong": 0,
                "n_true_positives": 0, "n_false_positives": 0,
                "n_false_negatives": 0, "n_true_negatives": 0,
                "examples": [],
            }
            THRESHOLD = 5e-4
            for p in predictions:
                tca_str = p.get("tca", "")
                if not tca_str or tca_str > now_str:
                    continue  # only resolved pairs (TCA in past)
                predicted_action = p.get("action_recommended", False)
                actual_exceeded = p.get("current_pc", 0) >= THRESHOLD
                correct = predicted_action == actual_exceeded
                if correct:
                    track_record["n_correct"] += 1
                else:
                    track_record["n_wrong"] += 1
                if predicted_action and actual_exceeded:
                    track_record["n_true_positives"] += 1
                elif predicted_action and not actual_exceeded:
                    track_record["n_false_positives"] += 1
                elif not predicted_action and actual_exceeded:
                    track_record["n_false_negatives"] += 1
                else:
                    track_record["n_true_negatives"] += 1
                # Collect ALL resolved examples for comprehensive validation
                track_record["examples"].append({
                    "sat1_name": p["sat1_name"],
                    "sat2_name": p["sat2_name"],
                    "sat1_norad": p["sat1_norad"],
                    "sat2_norad": p["sat2_norad"],
                    "tca": tca_str,
                    "predicted_action": predicted_action,
                    "actual_exceeded": actual_exceeded,
                    "exceedance_probability": p.get("exceedance_probability", 0),
                    "ensemble_probability": p.get("ensemble_probability"),
                    "current_pc": p.get("current_pc", 0),
                    "forecast_pc": p.get("forecast_pc", 0),
                    "risk_direction": p.get("risk_direction", ""),
                    "n_updates": p.get("n_updates", 0),
                    "correct": correct,
                })
            # Sort: wrong predictions first, then by exceedance_probability descending
            examples = track_record["examples"]
            wrong_ex = sorted([e for e in examples if not e["correct"]],
                              key=lambda e: e.get("exceedance_probability", 0), reverse=True)
            right_ex = sorted([e for e in examples if e["correct"]],
                              key=lambda e: e.get("exceedance_probability", 0), reverse=True)
            # Keep up to 20 wrong + 30 right = 50 examples for the webapp
            track_record["examples"] = wrong_ex[:20] + right_ex[:30]
            forecast_data["track_record"] = track_record

            # Append daily snapshot to prediction_history.jsonl for confidence evolution tracking.
            # Each line records today's prediction for one pair, enabling time-series
            # analysis of how model confidence evolves as TCA approaches.
            history_path = LOG_DIR / "prediction_history.jsonl"
            today_str_snap = datetime.utcnow().strftime("%Y-%m-%d")
            try:
                with open(history_path, "a") as hf:
                    for p in predictions:
                        hf.write(json.dumps({
                            "date": today_str_snap,
                            "sat1_norad": p["sat1_norad"],
                            "sat2_norad": p["sat2_norad"],
                            "tca": p.get("tca", ""),
                            "hours_to_tca": p.get("time_to_tca_hours", 0),
                            "current_pc": p.get("current_pc", 0),
                            "exceedance_prob": p.get("exceedance_probability", 0),
                            "ensemble_prob": p.get("ensemble_probability"),
                            "action_recommended": p.get("action_recommended", False),
                            "risk_direction": p.get("risk_direction", ""),
                            "n_updates": p.get("n_updates", 0),
                        }, default=_json_default) + "\n")
                print(f"  Appended {len(predictions)} prediction snapshots to prediction_history.jsonl")
            except Exception as e:
                print(f"  prediction_history.jsonl write failed (non-fatal): {e}")

            forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
            with open(forecast_path, "w") as f:
                json.dump(forecast_data, f, indent=2, default=_json_default)
            mode = fmetrics.get("mode", "heuristic")
            n_resolved = track_record["n_correct"] + track_record["n_wrong"]
            print(f"  CDM forecast ({mode}): {fmetrics.get('n_pairs_total', 0)} pairs, "
                  f"{sum(1 for p in predictions if p['action_recommended'])} actionable")
            if n_resolved > 0:
                tr_acc = track_record["n_correct"] / n_resolved
                print(f"  Track record: {track_record['n_correct']}/{n_resolved} correct ({tr_acc:.1%}) "
                      f"— TP={track_record['n_true_positives']}, FP={track_record['n_false_positives']}, "
                      f"FN={track_record['n_false_negatives']}, TN={track_record['n_true_negatives']}")
            if test_metrics:
                print(f"  Model accuracy: {test_metrics.get('accuracy', 0):.1%}, "
                      f"F1: {test_metrics.get('f1', 0):.3f}, "
                      f"AUC-PR: {test_metrics.get('auc_pr', 0):.3f}")
        else:
            print("  No CDM store found — skipping forecast")
    except Exception as e:
        print(f"  CDM forecast failed (non-fatal): {e}")

    # Run LSTM transfer learning model (Kelvins → Space-Track)
    print("\nRunning LSTM transfer learning forecast ...")
    try:
        from src.model.cdm_lstm import CDMLSTMModel
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        kelvins_csv = ROOT / "data" / "cdm" / "Collision Avoidance Challenge - Dataset" / "kelvins_competition_data" / "train_data.csv"
        emergency_csv = ROOT / "data" / "cdm_spacetrack" / "cdm_spacetrack_emergency.csv"
        lstm_ckpt = ROOT / "models" / "cdm_lstm.pt"

        if cdm_store.exists() and kelvins_csv.exists():
            # Load existing or train fresh
            if lstm_ckpt.exists():
                lstm_model = CDMLSTMModel.load(str(lstm_ckpt))
                # Re-finetune on latest data
                ft_metrics = lstm_model.finetune_spacetrack(
                    str(cdm_store),
                    str(emergency_csv) if emergency_csv.exists() else None,
                )
            else:
                lstm_model = CDMLSTMModel()
                lstm_model.pretrain_kelvins(str(kelvins_csv))
                ft_metrics = lstm_model.finetune_spacetrack(
                    str(cdm_store),
                    str(emergency_csv) if emergency_csv.exists() else None,
                )
            lstm_model.save(str(lstm_ckpt))

            ft_test = ft_metrics.get("test", {})
            print(f"  LSTM fine-tune: acc={ft_test.get('accuracy', 0):.1%}, "
                  f"F1={ft_test.get('f1', 0):.3f}, "
                  f"prec={ft_test.get('precision', 0):.3f}, "
                  f"rec={ft_test.get('recall', 0):.3f}")
        else:
            print("  Skipping LSTM — missing Kelvins or CDM data")
    except Exception as e:
        print(f"  LSTM forecast failed (non-fatal): {e}")

    # Run CDMSequenceModel (multi-task regression: max Pc, min miss, escalation)
    print("\nRunning CDM Sequence regression model ...")
    seq_predictions = {}  # keyed by (sat1_norad, sat2_norad) for merging into forecast JSON
    seq_regression_metrics = {}
    try:
        import torch as _torch_check  # verify torch available
        from src.model.cdm_sequence_model import CDMSequenceModel
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        kelvins_csv = ROOT / "data" / "cdm" / "Collision Avoidance Challenge - Dataset" / "kelvins_competition_data" / "train_data.csv"
        seq_ckpt = ROOT / "models" / "cdm_sequence_model.pt"

        if cdm_store.exists():
            if seq_ckpt.exists():
                print("  Loading existing CDMSequenceModel checkpoint ...")
                seq_model = CDMSequenceModel.load(str(seq_ckpt))
                ft = seq_model.finetune_spacetrack(str(cdm_store))
                seq_regression_metrics = ft.get("test", {})
            else:
                seq_model = CDMSequenceModel()
                if kelvins_csv.exists():
                    seq_model.pretrain_kelvins(str(kelvins_csv))
                ft = seq_model.finetune_spacetrack(str(cdm_store))
                seq_regression_metrics = ft.get("test", {})

            seq_model.save(str(seq_ckpt))

            # Run predictions on all pairs
            if seq_model.trained:
                pair_map = seq_model._load_spacetrack_pairs(str(cdm_store))
                for pair_key, cdms in pair_map.items():
                    pred = seq_model.predict(cdms)
                    if "error" not in pred:
                        n1, n2, tca_date = pair_key
                        # Key by (norad_pair, tca_date) so multiple events match correctly
                        seq_predictions[(min(n1, n2), max(n1, n2), tca_date)] = pred
                print(f"  CDMSequenceModel: {len(seq_predictions)} pair predictions")
                if seq_regression_metrics:
                    print(f"  Regression MAE(log10_pc)={seq_regression_metrics.get('mae_log10_pc', 0):.3f}, "
                          f"corr={seq_regression_metrics.get('correlation_pc', 0):.3f}")
        else:
            print("  No CDM store found — skipping sequence model")
    except ImportError:
        print("  CDMSequenceModel skipped (torch not available)")
    except Exception as e:
        print(f"  CDMSequenceModel failed (non-fatal): {e}")

    # Merge sequence model predictions + ensemble into cdm_forecast.json
    print("\nComputing ensemble predictions ...")
    try:
        forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
        if forecast_path.exists():
            with open(forecast_path) as f:
                forecast_data = json.load(f)
            n_ensemble = 0
            for pair_entry in forecast_data.get("pairs", []):
                n1 = pair_entry.get("sat1_norad")
                n2 = pair_entry.get("sat2_norad")
                if n1 is None or n2 is None:
                    continue
                tca_date = pair_entry.get("tca", "")[:10]
                key = (min(n1, n2), max(n1, n2), tca_date)
                sp = seq_predictions.get(key, {})

                # LSTM regression fields
                pair_entry["predicted_max_pc"] = sp.get("predicted_max_pc")
                pair_entry["predicted_max_log10_pc"] = sp.get("predicted_max_log10_pc")
                pair_entry["predicted_min_miss_km"] = sp.get("predicted_min_miss_km")
                pair_entry["lstm_escalation_prob"] = sp.get("escalation_probability")
                pair_entry["attention_weights"] = sp.get("attention_weights")
                # Trim attention_weights to match time_series length
                ts_len = len(pair_entry.get("time_series", []))
                if pair_entry.get("attention_weights") and len(pair_entry["attention_weights"]) > ts_len and ts_len > 0:
                    pair_entry["attention_weights"] = pair_entry["attention_weights"][:ts_len]

                # Ensemble: p = w1*LR + w2*LSTM + w3*sigmoid((pred_max_log10_pc + 3.3) * 5)
                lr_prob = pair_entry.get("exceedance_probability", 0)
                lstm_prob = sp.get("escalation_probability")
                pred_max = sp.get("predicted_max_log10_pc")

                if lstm_prob is not None and pred_max is not None:
                    # Sigmoid signal from regression: how far above threshold
                    pc_signal = 1.0 / (1.0 + math.exp(-SIGMOID_STEEPNESS * (pred_max - LOG10_PC_THRESHOLD)))
                    p_ens = ENSEMBLE_W_LR * lr_prob + ENSEMBLE_W_LSTM * lstm_prob + ENSEMBLE_W_REGRESSION * pc_signal
                    pair_entry["ensemble_probability"] = round(p_ens, 4)

                    # Uncertainty interval (±1 MAE around predicted max)
                    mae = seq_regression_metrics.get("mae_log10_pc", 0.3)
                    p_upper = 1.0 / (1.0 + math.exp(-SIGMOID_STEEPNESS * (pred_max + mae - LOG10_PC_THRESHOLD)))
                    p_lower = 1.0 / (1.0 + math.exp(-SIGMOID_STEEPNESS * (pred_max - mae - LOG10_PC_THRESHOLD)))
                    pair_entry["exceedance_upper"] = round(max(p_ens, ENSEMBLE_W_LR * lr_prob + ENSEMBLE_W_LSTM * lstm_prob + ENSEMBLE_W_REGRESSION * p_upper), 4)
                    pair_entry["exceedance_lower"] = round(min(p_ens, ENSEMBLE_W_LR * lr_prob + ENSEMBLE_W_LSTM * lstm_prob + ENSEMBLE_W_REGRESSION * p_lower), 4)
                    n_ensemble += 1
                else:
                    # No LSTM prediction — use LR only
                    pair_entry["ensemble_probability"] = round(lr_prob, 4) if lr_prob else None
                    pair_entry["exceedance_upper"] = None
                    pair_entry["exceedance_lower"] = None

            # Add regression metrics
            if seq_regression_metrics:
                forecast_data["regression_metrics"] = {
                    "mae_log10_pc": seq_regression_metrics.get("mae_log10_pc", 0),
                    "rmse_log10_pc": seq_regression_metrics.get("rmse_log10_pc", 0),
                    "mae_log10_miss": seq_regression_metrics.get("mae_log10_miss", 0),
                    "correlation_pc": seq_regression_metrics.get("correlation_pc", 0),
                    "esc_f1": seq_regression_metrics.get("esc_f1", 0),
                    "ece": seq_regression_metrics.get("ece", 0),
                    "temperature": seq_regression_metrics.get("temperature", 1.0),
                    "n": seq_regression_metrics.get("n", 0),
                }
            with open(forecast_path, "w") as f:
                json.dump(forecast_data, f, indent=2, default=_json_default)
            n_total_pairs = len(forecast_data.get("pairs", []))
            n_lr_only = n_total_pairs - n_ensemble
            lstm_coverage_pct = (n_ensemble / n_total_pairs * 100) if n_total_pairs > 0 else 0
            print(f"  Merged {len(seq_predictions)} LSTM + {n_ensemble} ensemble predictions into cdm_forecast.json")
            print(f"  Ensemble coverage: {n_ensemble}/{n_total_pairs} pairs ({lstm_coverage_pct:.1f}%) have full ensemble; {n_lr_only} use LR-only fallback")
            if lstm_coverage_pct < 50:
                print(f"  WARNING: Low LSTM coverage ({lstm_coverage_pct:.1f}%) — ensemble quality degraded")
    except Exception as e:
        print(f"  Merge into cdm_forecast.json failed (non-fatal): {e}")

    # ── Shadow ensemble: experimental alternative with GNN ──
    # Computes a second hidden prediction using GNN as the non-linear component.
    # Stored in forecast JSON but not displayed on frontend. Compared against
    # primary ensemble in track_record to determine if it's better.
    print("\nComputing shadow ensemble (experimental) ...")
    try:
        import torch
        gnn_ckpt_path = ROOT / "models" / "conjunction_gnn.pt"
        forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
        if gnn_ckpt_path.exists() and forecast_path.exists():
            gnn_ckpt = torch.load(str(gnn_ckpt_path), map_location="cpu", weights_only=False)
            if gnn_ckpt.get("trained"):
                # Rebuild edge features for current pairs
                sat_idx = gnn_ckpt["sat_idx"]
                node_features_g = gnn_ckpt["node_features"]
                node_agg_g = gnn_ckpt["node_agg"]
                gnn_mu = gnn_ckpt["norm_mean"]
                gnn_sd = gnn_ckpt["norm_std"]
                input_dim = gnn_ckpt["input_dim"]

                # Load the MLP
                from scripts.train_supplementary import EdgeMLP  # noqa
                # Can't import EdgeMLP directly since it's defined inside train_gnn
                # Reconstruct it
                class _EdgeMLP(torch.nn.Module):
                    def __init__(self, input_dim, hidden=64, dropout=0.3):
                        super().__init__()
                        self.net = torch.nn.Sequential(
                            torch.nn.Linear(input_dim, hidden), torch.nn.GELU(), torch.nn.Dropout(dropout),
                            torch.nn.Linear(hidden, 32), torch.nn.GELU(), torch.nn.Dropout(dropout),
                            torch.nn.Linear(32, 1),
                        )
                    def forward(self, x):
                        return self.net(x).squeeze(-1)

                gnn_model = _EdgeMLP(input_dim)
                gnn_model.load_state_dict(gnn_ckpt["model_state_dict"])
                gnn_model.eval()

                with open(forecast_path) as f:
                    forecast_data = json.load(f)

                n_shadow = 0
                shadow_correct = 0
                shadow_wrong = 0
                for pair_entry in forecast_data.get("pairs", []):
                    n1 = pair_entry.get("sat1_norad")
                    n2 = pair_entry.get("sat2_norad")
                    if n1 is None or n2 is None:
                        continue

                    # Build edge feature vector matching GNN training format
                    i = sat_idx.get(min(n1, n2))
                    j = sat_idx.get(max(n1, n2))
                    if i is None or j is None:
                        continue  # satellite not in GNN graph

                    pc = pair_entry.get("current_pc", 0)
                    miss = pair_entry.get("current_miss_km", 100)
                    n_updates = pair_entry.get("n_updates", 1)

                    # Concatenate: node_i + node_j + edge_feat + graph_agg
                    edge_feat = np.array([math.log1p(n_updates), math.log1p(miss)])
                    row = np.concatenate([
                        node_features_g[i], node_features_g[j],
                        edge_feat, node_agg_g[i], node_agg_g[j]
                    ])

                    # GNN prediction
                    x_norm = torch.tensor((row - gnn_mu) / (gnn_sd + 1e-8), dtype=torch.float32).unsqueeze(0)
                    with torch.no_grad():
                        gnn_prob = float(torch.sigmoid(gnn_model(x_norm)).item())

                    # Shadow ensemble: uses calibrated weights from stacking meta-learner
                    _cw_path = ROOT / "models" / "ensemble_weights.json"
                    sw_lr, sw_lstm, sw_gnn = 0.35, 0.30, 0.35  # defaults
                    if _cw_path.exists():
                        try:
                            _cw = json.load(open(_cw_path))["weights"]
                            sw_lr = _cw.get("LR", sw_lr)
                            sw_lstm = _cw.get("BiLSTM_signal", sw_lstm)
                            sw_gnn = _cw.get("GNN", sw_gnn)
                        except Exception:
                            pass
                    lr_prob = pair_entry.get("exceedance_probability", 0)
                    lstm_prob = pair_entry.get("lstm_escalation_prob")
                    if lstm_prob is not None:
                        shadow_ens = sw_lr * lr_prob + sw_lstm * lstm_prob + sw_gnn * gnn_prob
                    else:
                        total = sw_lr + sw_gnn
                        shadow_ens = (sw_lr/total) * lr_prob + (sw_gnn/total) * gnn_prob if total > 0 else lr_prob

                    pair_entry["shadow_ensemble"] = round(shadow_ens, 4)
                    pair_entry["gnn_probability"] = round(gnn_prob, 4)
                    n_shadow += 1

                    # Track shadow accuracy on resolved pairs
                    tca_str = pair_entry.get("tca", "")
                    now_str = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")
                    if tca_str and tca_str <= now_str:
                        actual = pair_entry.get("current_pc", 0) >= PC_ESCALATION_THRESHOLD
                        shadow_pred = shadow_ens >= 0.5
                        if shadow_pred == actual:
                            shadow_correct += 1
                        else:
                            shadow_wrong += 1

                # Store shadow metrics
                shadow_total = shadow_correct + shadow_wrong
                forecast_data["shadow_ensemble"] = {
                    "weights": {
                        "LR": round(sw_lr, 4),
                        "BiLSTM": round(sw_lstm, 4),
                        "GNN": round(sw_gnn, 4),
                        "source": "calibrated" if _cw_path.exists() else "default",
                    },
                    "n_predictions": n_shadow,
                    "n_resolved": shadow_total,
                    "n_correct": shadow_correct,
                    "accuracy": round(shadow_correct / max(shadow_total, 1), 4),
                }
                # Compare against primary
                primary_tr = forecast_data.get("track_record", {})
                primary_acc = primary_tr.get("n_correct", 0) / max(primary_tr.get("n_correct", 0) + primary_tr.get("n_wrong", 0), 1)
                shadow_acc = shadow_correct / max(shadow_total, 1)
                forecast_data["shadow_ensemble"]["vs_primary"] = round(shadow_acc - primary_acc, 4)

                with open(forecast_path, "w") as f:
                    json.dump(forecast_data, f, indent=2, default=_json_default)
                print(f"  Shadow ensemble: {n_shadow} pairs scored, {shadow_total} resolved")
                if shadow_total > 0:
                    print(f"  Shadow accuracy: {shadow_correct}/{shadow_total} ({shadow_acc:.1%}) vs primary {primary_acc:.1%} (delta={shadow_acc - primary_acc:+.1%})")
            else:
                print("  GNN checkpoint not trained — skipping shadow ensemble")
        else:
            print("  GNN checkpoint or forecast not found — skipping shadow ensemble")
    except Exception as e:
        print(f"  Shadow ensemble failed (non-fatal): {e}")

    # Run conformal prediction analysis
    print("\nRunning conformal prediction analysis ...")
    conformal_results = {}
    try:
        from src.model.conformal import run_conformal_analysis
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        if cdm_store.exists():
            conformal_results = run_conformal_analysis(str(cdm_store), alpha=0.10)
            # Merge conformal intervals into forecast JSON
            forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
            if forecast_path.exists() and conformal_results.get("regression"):
                with open(forecast_path) as f:
                    forecast_data = json.load(f)
                reg_cov = conformal_results["regression"]["test_coverage"]
                cls_cov = conformal_results["classification"]["test_coverage"]
                forecast_data["conformal"] = {
                    "alpha": 0.10,
                    "regression_coverage": reg_cov["empirical_coverage"],
                    "classification_coverage": cls_cov["empirical_coverage"],
                    "interval_width_log10pc": reg_cov["mean_interval_width"],
                    "q_hat": conformal_results["regression"]["calibration"]["q_hat"],
                    "n_calibration": conformal_results["n_calibration"],
                }
                with open(forecast_path, "w") as f:
                    json.dump(forecast_data, f, indent=2, default=_json_default)
                print(f"  Conformal: {reg_cov['empirical_coverage']:.1%} regression coverage, "
                      f"q_hat={conformal_results['regression']['calibration']['q_hat']:.3f}")
    except Exception as e:
        print(f"  Conformal analysis failed (non-fatal): {e}")

    # Run autoregressive CDM forecaster
    print("\nRunning autoregressive CDM forecaster ...")
    try:
        from src.model.cdm_autoregressive import CDMAutoregressive
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        ar_ckpt = ROOT / "models" / "cdm_autoregressive.pt"
        if cdm_store.exists():
            ar_model = CDMAutoregressive()
            ar_metrics = ar_model.train(str(cdm_store), epochs=50)
            ar_model.save(str(ar_ckpt))
            print(f"  Autoregressive: MAE_pc={ar_metrics.get('mae_log10_pc', 0):.3f}, "
                  f"corr={ar_metrics.get('correlation_pc', 0):.3f}")

            # Add forecasts to cdm_forecast.json
            forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
            if forecast_path.exists():
                with open(forecast_path) as f:
                    forecast_data = json.load(f)
                forecast_data["autoregressive_metrics"] = ar_metrics

                # Generate forecasts for active pairs
                pair_map = ar_model._load_pairs(str(cdm_store))
                for pair_entry in forecast_data.get("pairs", []):
                    n1 = pair_entry["sat1_norad"]
                    n2 = pair_entry["sat2_norad"]
                    tca_date = pair_entry.get("tca", "")[:10]
                    key = (min(n1, n2), max(n1, n2), tca_date)
                    cdms = pair_map.get(key, [])
                    if len(cdms) >= 3:
                        fc = ar_model.forecast(cdms, n_steps=3, mc_samples=15)
                        pair_entry["forecast_steps"] = fc

                with open(forecast_path, "w") as f:
                    json.dump(forecast_data, f, indent=2, default=_json_default)
    except Exception as e:
        print(f"  Autoregressive failed (non-fatal): {e}")

    # Generate AI risk summaries for all pairs
    print("\nGenerating AI risk summaries ...")
    try:
        from src.model.event_summarizer import summarize_pair
        forecast_path = ROOT / "webapp-react" / "public" / "cdm_forecast.json"
        if forecast_path.exists():
            with open(forecast_path) as f:
                forecast_data = json.load(f)
            n_summarized = 0
            for pair_entry in forecast_data.get("pairs", []):
                pair_entry["ai_summary"] = summarize_pair(pair_entry)
                n_summarized += 1
            with open(forecast_path, "w") as f:
                json.dump(forecast_data, f, indent=2, default=_json_default)
            print(f"  Generated {n_summarized} AI risk summaries")
    except Exception as e:
        print(f"  AI summaries failed (non-fatal): {e}")

    # Run GNN conjunction network model
    print("\nRunning Conjunction GNN ...")
    try:
        from src.model.conjunction_gnn import ConjunctionGNNModel, HAS_PYG
        cdm_store = LOG_DIR / "cdm_store.jsonl"
        tle_path = ROOT / "webapp-react" / "public" / "latest_tles.json"
        gnn_ckpt = ROOT / "models" / "conjunction_gnn.pt"
        if HAS_PYG and cdm_store.exists():
            if gnn_ckpt.exists():
                gnn_model = ConjunctionGNNModel.load(str(gnn_ckpt))
            else:
                gnn_model = ConjunctionGNNModel()
            gnn_metrics = gnn_model.train(
                str(cdm_store),
                tle_path=str(tle_path) if tle_path.exists() else None,
                epochs=80,
            )
            gnn_model.save(str(gnn_ckpt))
            test_m = gnn_metrics.get("test", {})
            print(f"  GNN: F1={test_m.get('f1', 0):.3f}, Acc={test_m.get('accuracy', 0):.1%}, "
                  f"{gnn_metrics.get('n_nodes', 0)} nodes, {gnn_metrics.get('n_pairs', 0)} pairs")
        elif not HAS_PYG:
            print("  GNN skipped (torch_geometric not installed)")
    except Exception as e:
        print(f"  GNN failed (non-fatal): {e}")

    print(f"\n{'='*60}")
    print(f"  Daily pipeline complete!")
    print(f"  Pairs screened: {len(candidates)}")
    print(f"  Predictions logged: {top_k}")
    cdm_acc = validation.get("cdm_forecast_accuracy", {})
    if cdm_acc.get("accuracy"):
        print(f"  CDM forecast accuracy: {cdm_acc['accuracy']:.1%} "
              f"(F1={cdm_acc.get('f1', 0):.3f}, n_test={cdm_acc.get('n_test', 0)})")
    if conformal_results.get("regression"):
        reg_cov = conformal_results["regression"]["test_coverage"]
        print(f"  Conformal: {reg_cov['empirical_coverage']:.1%} coverage @ 90% target")
    print(f"{'='*60}")


def _load_cdm_alerts(tle_by_id: dict, today_str: str, forward_days: int = 7, min_pc: float = 1e-7) -> list[dict]:
    """Load CDM-sourced alerts from local store.

    CDMs with TCA in the next `forward_days` and Pc >= min_pc are included.
    Each CDM becomes an alert candidate ranked by Pc (highest risk first).
    """
    from src.data.spacetrack_crossref import _load_local_cdms

    all_cdms = _load_local_cdms()
    if not all_cdms:
        return []

    now = datetime.utcnow()
    cutoff_start = now.strftime("%Y-%m-%dT%H:%M:%S")
    cutoff_end = (now + timedelta(days=forward_days)).strftime("%Y-%m-%dT%H:%M:%S")

    # Filter: future TCA within window, meets Pc threshold
    cdm_alerts = []
    seen_pairs = set()
    for cdm in all_cdms:
        tca = cdm.get("tca", "")
        pc = cdm.get("pc", 0)
        if not tca or pc < min_pc:
            continue
        # Keep CDMs with TCA in the future (or very recent past, within 24h)
        recent_cutoff = (now - timedelta(hours=24)).strftime("%Y-%m-%dT%H:%M:%S")
        if tca < recent_cutoff or tca > cutoff_end:
            continue

        n1, n2 = cdm.get("sat1_norad", 0), cdm.get("sat2_norad", 0)
        pair_key = (min(n1, n2), max(n1, n2))
        if pair_key in seen_pairs:
            continue  # One alert per pair (highest CDM_ID = most recent)
        seen_pairs.add(pair_key)

        # Compute altitude from TLEs if available
        altitude_km = 0.0
        tle1 = tle_by_id.get(n1)
        tle2 = tle_by_id.get(n2)
        if tle1:
            mm = float(tle1.get("MEAN_MOTION", 0))
            if mm > 0:
                altitude_km = mean_motion_to_sma(mm) - EARTH_RADIUS_KM
        elif tle2:
            mm = float(tle2.get("MEAN_MOTION", 0))
            if mm > 0:
                altitude_km = mean_motion_to_sma(mm) - EARTH_RADIUS_KM

        # Hours until TCA
        try:
            tca_dt = datetime.fromisoformat(tca.replace("Z", "+00:00").replace("+00:00", ""))
            tca_hours = (tca_dt - now).total_seconds() / 3600.0
        except Exception:
            tca_hours = None

        cdm_alerts.append({
            "sat1_norad": n1,
            "sat2_norad": n2,
            "sat1_name": cdm.get("sat1_name", "UNKNOWN"),
            "sat2_name": cdm.get("sat2_name", "UNKNOWN"),
            "cdm_pc": pc,
            "cdm_miss_distance_km": cdm.get("miss_distance_km", 0),
            "cdm_tca": tca,
            "cdm_id": cdm.get("cdm_id", ""),
            "sat1_type": cdm.get("sat1_type", ""),
            "sat2_type": cdm.get("sat2_type", ""),
            "emergency_reportable": cdm.get("emergency_reportable", ""),
            "altitude_km": altitude_km,
            "tca_hours": tca_hours,
            "source": "cdm",
        })

    # Sort by Pc descending (highest risk first)
    cdm_alerts.sort(key=lambda c: c.get("cdm_pc", 0), reverse=True)
    return cdm_alerts


def generate_webapp_alerts(candidates: list[dict], tles: list[dict], today_str: str, top_k: int = 20):
    """Generate webapp-react/public/latest_alerts.json.

    Uses a two-source strategy:
      1. CDM-sourced alerts (primary): Real Pc from Space-Track CDMs
      2. TLE-screened alerts (fallback): SGP4 forward TCA for heuristic candidates

    CDM alerts are ranked by Pc and take priority. TLE-screened alerts fill
    remaining slots for objects not covered by CDMs.
    """
    ALERTS_PATH = ROOT / "webapp-react" / "public" / "latest_alerts.json"
    MAX_ALERT_DISTANCE_KM = 200.0
    TCA_SCAN_COUNT = 200

    # Build TLE lookup by NORAD ID for SGP4 propagation
    tle_by_id: dict[int, dict] = {}
    for tle in tles:
        nid = int(tle.get("NORAD_CAT_ID", 0))
        if nid > 0:
            tle_by_id[nid] = tle

    # ---- Source 1: CDM-powered alerts (real Pc values) ----
    cdm_alerts = []
    try:
        cdm_alerts = _load_cdm_alerts(tle_by_id, today_str)
        if cdm_alerts:
            print(f"  CDM alerts: {len(cdm_alerts)} pairs with future TCA "
                  f"(max Pc={cdm_alerts[0]['cdm_pc']:.4e})")
    except Exception as e:
        print(f"  CDM alert loading failed: {e}")

    # ---- Source 2: TLE-screened alerts (SGP4 forward TCA) ----
    tle_alerts = []
    try:
        from src.data.counterfactual import compute_forward_tca, compute_forward_trajectory, compute_tca_trail, SGP4_AVAILABLE
        if SGP4_AVAILABLE and candidates:
            scan_count = min(TCA_SCAN_COUNT, len(candidates))
            print(f"  Computing TCA for top {scan_count} heuristic candidates ...")
            tca_results = []
            for cand in candidates[:scan_count]:
                tle1 = tle_by_id.get(cand["sat1_norad"])
                tle2 = tle_by_id.get(cand["sat2_norad"])
                if not tle1 or not tle2:
                    continue
                result = compute_forward_tca(tle1, tle2, hours_forward=120.0, step_minutes=10.0)
                min_dist = result.get("tca_min_distance_km")
                if min_dist is not None:
                    cand["tca_hours"] = result["tca_hours"]
                    cand["tca_min_distance_km"] = min_dist
                    cand["source"] = "tle_screening"
                    tca_results.append(cand)

            print(f"  TCA computed for {len(tca_results)} pairs")
            tca_results.sort(key=lambda c: c["tca_min_distance_km"])
            tle_alerts = tca_results
    except ImportError:
        print("  counterfactual module not available — TLE screening skipped")

    # ---- Merge: CDM alerts first, then TLE alerts for uncovered pairs ----
    cdm_pair_set = set()
    for a in cdm_alerts:
        n1, n2 = a["sat1_norad"], a["sat2_norad"]
        cdm_pair_set.add((min(n1, n2), max(n1, n2)))

    # Deduplicate: limit each satellite to max 2 appearances
    sat_counts: dict[int, int] = {}
    selected_cdm = []
    for alert in cdm_alerts:
        n1, n2 = alert["sat1_norad"], alert["sat2_norad"]
        if sat_counts.get(n1, 0) >= 2 or sat_counts.get(n2, 0) >= 2:
            continue
        selected_cdm.append(alert)
        sat_counts[n1] = sat_counts.get(n1, 0) + 1
        sat_counts[n2] = sat_counts.get(n2, 0) + 1
        if len(selected_cdm) >= top_k:
            break

    # Fill remaining slots with TLE-screened alerts
    selected_tle = []
    remaining = top_k - len(selected_cdm)
    if remaining > 0:
        for cand in tle_alerts:
            n1, n2 = cand["sat1_norad"], cand["sat2_norad"]
            pair_key = (min(n1, n2), max(n1, n2))
            if pair_key in cdm_pair_set:
                continue
            if sat_counts.get(n1, 0) >= 2 or sat_counts.get(n2, 0) >= 2:
                continue
            selected_tle.append(cand)
            sat_counts[n1] = sat_counts.get(n1, 0) + 1
            sat_counts[n2] = sat_counts.get(n2, 0) + 1
            if len(selected_tle) >= remaining:
                break

    print(f"  Selected: {len(selected_cdm)} CDM + {len(selected_tle)} TLE-screened")

    # ---- Fetch missing TLEs from Space-Track for CDM objects ----
    all_selected = selected_cdm + selected_tle
    missing_norads = set()
    for alert in all_selected:
        for nid in (alert["sat1_norad"], alert["sat2_norad"]):
            if nid and nid not in tle_by_id:
                missing_norads.add(nid)

    if missing_norads:
        print(f"  Fetching TLEs for {len(missing_norads)} CDM objects not in catalog...")
        try:
            from src.data.spacetrack_crossref import _get_session
            session = _get_session()
            if session:
                # Batch fetch TLEs from Space-Track GP catalog
                norad_list = ",".join(str(n) for n in sorted(missing_norads))
                url = (f"https://www.space-track.org/basicspacedata/query"
                       f"/class/gp/NORAD_CAT_ID/{norad_list}"
                       f"/orderby/NORAD_CAT_ID/format/json")
                resp = session.get(url, timeout=60)
                if resp.status_code == 200:
                    extra_tles = resp.json()
                    # Deduplicate — keep latest epoch per NORAD
                    for tle in extra_tles:
                        nid = int(tle.get("NORAD_CAT_ID", 0))
                        if nid > 0:
                            existing = tle_by_id.get(nid)
                            if not existing or tle.get("EPOCH", "") > existing.get("EPOCH", ""):
                                tle_by_id[nid] = tle
                    fetched = len(set(int(t.get("NORAD_CAT_ID", 0)) for t in extra_tles))
                    print(f"  Got TLEs for {fetched}/{len(missing_norads)} missing objects")
                else:
                    print(f"  Space-Track GP query failed: HTTP {resp.status_code}")
        except Exception as e:
            print(f"  Space-Track TLE fetch failed: {e}")

    # ---- Enrich with trajectories ----
    traj_computed = 0
    try:
        from src.data.counterfactual import compute_forward_tca, compute_forward_trajectory, compute_tca_trail, SGP4_AVAILABLE
        if SGP4_AVAILABLE:
            for alert in all_selected:
                tle1 = tle_by_id.get(alert["sat1_norad"])
                tle2 = tle_by_id.get(alert["sat2_norad"])
                if not tle1 or not tle2:
                    continue
                # Store TLEs in alert so frontend can do client-side propagation
                alert["tle1"] = tle1
                alert["tle2"] = tle2
                # Pre-compute trajectory (5-day sparse) and trail (±30min dense)
                traj = compute_forward_trajectory(tle1, tle2, hours_forward=120.0, step_minutes=20.0)
                if traj:
                    alert["trajectory"] = traj
                    traj_computed += 1
                tca_h = alert.get("tca_hours")
                if tca_h is not None and tca_h > 0:
                    trail = compute_tca_trail(tle1, tle2, tca_h)
                    if trail:
                        alert["trail"] = trail
            print(f"  Enriched {traj_computed}/{len(all_selected)} alerts with trajectory + trail")
    except ImportError:
        pass

    # ---- Convert to webapp JSON format ----
    pairs = []
    for alert in all_selected:
        source = alert.get("source", "tle_screening")
        pair = {
            "name_1": alert["sat1_name"],
            "name_2": alert["sat2_name"],
            "norad_1": alert["sat1_norad"],
            "norad_2": alert["sat2_norad"],
            "altitude_km": round(float(alert.get("altitude_km", 0)), 1),
            "prediction_date": today_str,
            "source": source,
        }

        if source == "cdm":
            pair["risk_score"] = round(float(alert.get("cdm_pc", 0)), 10)
            pair["pc"] = float(alert.get("cdm_pc", 0))
            pair["miss_distance_km"] = round(float(alert.get("cdm_miss_distance_km", 0)), 1)
            pair["cdm_tca"] = alert.get("cdm_tca", "")
            pair["sat1_type"] = alert.get("sat1_type", "")
            pair["sat2_type"] = alert.get("sat2_type", "")
            pair["emergency_reportable"] = alert.get("emergency_reportable", "")
            pair["miss_estimate_km"] = round(float(alert.get("cdm_miss_distance_km", 0)), 1)
        else:
            risk = alert.get("risk_score", alert.get("model_risk_score", 0))
            miss = alert.get("model_miss_km", alert.get("miss_estimate_km", 0))
            pair["risk_score"] = round(float(risk), 4)
            pair["miss_estimate_km"] = round(float(miss), 1)

        if alert.get("tca_hours") is not None:
            pair["tca_hours"] = alert["tca_hours"]
        if alert.get("tca_min_distance_km") is not None:
            pair["tca_min_distance_km"] = alert["tca_min_distance_km"]
        if alert.get("trajectory"):
            pair["trajectory"] = alert["trajectory"]
        if alert.get("trail"):
            pair["trail"] = alert["trail"]
        # Include TLE data for client-side fallback propagation
        if alert.get("tle1"):
            pair["tle1"] = {k: alert["tle1"][k] for k in
                           ("OBJECT_NAME", "NORAD_CAT_ID", "EPOCH", "MEAN_MOTION",
                            "ECCENTRICITY", "INCLINATION", "RA_OF_ASC_NODE",
                            "ARG_OF_PERICENTER", "MEAN_ANOMALY", "BSTAR",
                            "MEAN_MOTION_DOT", "MEAN_MOTION_DDOT", "EPHEMERIS_TYPE",
                            "ELEMENT_SET_NO", "REV_AT_EPOCH", "CLASSIFICATION_TYPE")
                           if k in alert["tle1"]}

        pairs.append(pair)

    alerts = {
        "generated_at": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "prediction_date": today_str,
        "n_cdm_alerts": len(selected_cdm),
        "n_tle_alerts": len(selected_tle),
        "pairs": pairs,
    }

    ALERTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(ALERTS_PATH, "w") as f:
        json.dump(alerts, f, indent=2, default=_json_default)

    cdm_count = len(selected_cdm)
    tle_count = len(selected_tle)
    if pairs:
        top_pair = pairs[0]
        top_info = f"Pc={top_pair.get('pc', '?')}" if top_pair.get("source") == "cdm" else f"dist={top_pair.get('tca_min_distance_km', '?')} km"
        print(f"  Wrote {len(pairs)} alerts ({cdm_count} CDM + {tle_count} TLE, top: {top_info})")
    else:
        print("  Wrote 0 alerts")


def export_pipeline_stats():
    """Generate pipeline_stats.json for the webapp Pipeline dashboard tab."""
    import json
    from pathlib import Path

    webapp_path = Path("webapp-react/public/pipeline_stats.json")
    stats: dict = {"generated_at": datetime.utcnow().isoformat() + "Z"}

    # Fine-tune history
    ft_log = LOG_DIR / "finetune_log.jsonl"
    ft_history = []
    if ft_log.exists():
        for line in ft_log.read_text().strip().split("\n"):
            if not line.strip():
                continue
            try:
                rec = json.loads(line)
                ft_history.append({
                    "date": rec.get("date", "")[:10],
                    "pre_auc_pr": rec.get("pre_auc_pr", 0),
                    "post_auc_pr": rec.get("post_auc_pr", 0),
                    "keep_new_model": rec.get("keep_new_model", False),
                    "n_outcomes": rec.get("n_outcomes", 0),
                    "epochs_trained": rec.get("epochs_trained", 0),
                })
            except json.JSONDecodeError:
                continue
    stats["finetune_history"] = ft_history

    # Daily summaries
    ds_log = LOG_DIR / "daily_summaries.jsonl"
    daily_history = []
    if ds_log.exists():
        for line in ds_log.read_text().strip().split("\n"):
            if not line.strip():
                continue
            try:
                rec = json.loads(line)
                entry = {
                    "date": rec.get("date", ""),
                    "n_satellites_screened": rec.get("n_satellites_screened", 0),
                    "n_candidate_pairs": rec.get("n_candidate_pairs", 0),
                    "n_predictions_logged": rec.get("n_predictions_logged", 0),
                }
                val = rec.get("validation", {})
                if isinstance(val, dict) and val.get("n_maneuvers_total"):
                    entry["n_maneuvers"] = val["n_maneuvers_total"]
                daily_history.append(entry)
            except json.JSONDecodeError:
                continue
    stats["daily_history"] = daily_history

    # CDM stats
    cdm_store = LOG_DIR / "cdm_store.jsonl"
    cdm_stats = {"total_cdms": 0, "last_fetch": "", "fetch_count": 0,
                 "pc_high": 0, "pc_moderate": 0, "emergency_count": 0}
    if cdm_store.exists():
        total = 0
        pc_high = 0
        pc_mod = 0
        emrg = 0
        for line in cdm_store.read_text().strip().split("\n"):
            if not line.strip():
                continue
            try:
                rec = json.loads(line)
                total += 1
                pc = rec.get("pc", 0) or 0
                if pc >= 5e-4:
                    pc_high += 1
                elif pc >= 1e-4:
                    pc_mod += 1
                if rec.get("emergency_reportable") == "Y":
                    emrg += 1
            except json.JSONDecodeError:
                continue
        cdm_stats["total_cdms"] = total
        cdm_stats["pc_high"] = pc_high
        cdm_stats["pc_moderate"] = pc_mod
        cdm_stats["emergency_count"] = emrg

    fetch_log = LOG_DIR / "cdm_fetch_log.json"
    if fetch_log.exists():
        try:
            fl = json.loads(fetch_log.read_text())
            cdm_stats["last_fetch"] = fl.get("last_cdm_fetch", "")
            cdm_stats["fetch_count"] = fl.get("fetch_count", 0)
        except Exception:
            pass
    stats["cdm_stats"] = cdm_stats

    # CDM forecast model metrics (if model checkpoint exists)
    model_path = ROOT / "models" / "cdm_forecast.json"
    if model_path.exists():
        try:
            model_data = json.loads(model_path.read_text())
            stats["forecast_model"] = model_data.get("metrics", {})
        except Exception:
            pass

    # Space weather indices (last 30 days from cache)
    try:
        from src.data.space_weather import SpaceWeatherCache
        sw_cache = SpaceWeatherCache()
        today = datetime.utcnow()
        sw_records = []
        for d in range(30):
            date_str = (today - timedelta(days=d)).strftime("%Y-%m-%d")
            sw = sw_cache.get_indices(date_str)
            sw_records.append({
                "date": date_str,
                "f107": sw.get("f107", 0),
                "kp": sw.get("kp", 0),
                "ap": sw.get("ap", 0),
                "source": sw.get("source", "unknown"),
            })
        sw_records.reverse()  # oldest first
        stats["space_weather"] = {
            "current": sw_records[-1] if sw_records else {},
            "history": sw_records,
        }
    except Exception:
        pass

    webapp_path.parent.mkdir(parents=True, exist_ok=True)
    webapp_path.write_text(json.dumps(stats, indent=2))
    print(f"  Pipeline stats exported to {webapp_path}")


def archive_to_huggingface(logger: PredictionLogger):
    """Push accumulated prediction logs to HuggingFace Datasets."""
    import os
    hf_token = os.environ.get("HF_TOKEN", "")
    if not hf_token:
        print("  No HF_TOKEN — skipping archival")
        return

    try:
        from huggingface_hub import HfApi
        api = HfApi(token=hf_token)

        repo_id = "DominicTanzillo/panacea-predictions"

        # Create repo if it doesn't exist
        try:
            api.create_repo(repo_id, repo_type="dataset", exist_ok=True)
        except Exception:
            pass

        # Upload all local prediction logs
        log_dir = logger.local_dir
        for f in sorted(log_dir.glob("*.jsonl")):
            api.upload_file(
                path_or_fileobj=str(f),
                path_in_repo=f"logs/{f.name}",
                repo_id=repo_id,
                repo_type="dataset",
            )
        print(f"  Archived {len(list(log_dir.glob('*.jsonl')))} log files to HuggingFace")

    except ImportError:
        print("  huggingface_hub not installed — skipping archival")
    except Exception as e:
        print(f"  HuggingFace archival error: {e}")


if __name__ == "__main__":
    main()
